// Site data, generated by build.py from the record sheet (src/data/records.json).
import raw from "../data/records.json";

export type Verdict = "correct" | "partly" | "wrong" | "declined" | "unknown" | "untested" | "other";
export type RoundKey = "a" | "b";

export interface Round {
  answer: string;
  confidence: string;
  verdict: Verdict;
  verdictRaw: string;
  sources?: string;
}

export interface Row {
  n: string;
  title: string;
  address: string;
  a: Round;
  b: Round;
  locate: string;
  jianjiao: string;
  notes: string;
  poem: string[] | null;
}

export interface SiteData {
  meta: { built: string; source: string; sha256: string; summaryCheck: { status: string; detail: string } };
  counts: Record<RoundKey, Record<string, number>>;
  rows: Row[];
  method: { run: Record<string, string>; promptA: string; promptB: string };
}

export const DATA = raw as unknown as SiteData;
export const ROWS = DATA.rows;
export const TOTAL = ROWS.length;
export const POEM_COUNT = new Set(ROWS.map((r) => r.title)).size;

export const rowByN = (n: string | undefined) => ROWS.find((r) => r.n === n);
export const tested = (rnd: RoundKey) => ROWS.filter((r) => r[rnd].verdict !== "untested").length;
export const countBy = (rnd: RoundKey) => {
  const c: Record<string, number> = {};
  ROWS.forEach((r) => { c[r[rnd].verdict] = (c[r[rnd].verdict] || 0) + 1; });
  return c;
};
